import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname } from "node:path";

import type { ContentManifest } from "./manifest-types";

const generatedFileHeader = `/* eslint-disable */
// This file is generated by scripts/build-content.ts. Do not edit it manually.
import type { ContentManifest } from "../src/lib/content/manifest-types";

`;

const generatedModuleRegistryHeader = `/* eslint-disable */
// This file is generated by scripts/build-content.ts. Do not edit it manually.

`;

export function serializeContentManifest(manifest: ContentManifest) {
  const serializedManifest = JSON.stringify(manifest, null, 2)
    .replaceAll("\u2028", "\\u2028")
    .replaceAll("\u2029", "\\u2029");

  return `${generatedFileHeader}export const contentManifest = ${serializedManifest} as const satisfies ContentManifest;\n`;
}

export async function writeContentManifest(
  outputPath: string,
  manifest: ContentManifest,
) {
  const nextContent = serializeContentManifest(manifest);
  let currentContent: string | undefined;

  try {
    currentContent = await readFile(outputPath, "utf8");
  } catch (error) {
    if (
      !(error instanceof Error && "code" in error && error.code === "ENOENT")
    ) {
      throw error;
    }
  }

  if (currentContent === nextContent) {
    return { changed: false, outputPath } as const;
  }

  await mkdir(dirname(outputPath), { recursive: true });
  await writeFile(outputPath, nextContent, "utf8");
  return { changed: true, outputPath } as const;
}

function toGeneratedImportPath(sourcePath: string) {
  if (!sourcePath.startsWith("content/") || !sourcePath.endsWith(".mdx")) {
    throw new Error(`无法为内容模块生成安全导入路径：${sourcePath}`);
  }

  return `../${sourcePath}`;
}

function serializeLoaderMap(
  entries: readonly {
    readonly slug: string;
    readonly legacySlugs?: readonly string[];
    readonly sourcePath: string;
  }[],
) {
  const loaders = entries.flatMap(({ legacySlugs = [], slug, sourcePath }) =>
    [slug, ...legacySlugs].map(
      (routeSlug) =>
        `  ${JSON.stringify(routeSlug)}: () => import(${JSON.stringify(toGeneratedImportPath(sourcePath))}),`,
    ),
  );

  return `{
${loaders.join("\n")}
} as const`;
}

export function serializeContentModuleRegistry(manifest: ContentManifest) {
  return `${generatedModuleRegistryHeader}export const conceptContentLoaders = ${serializeLoaderMap(manifest.concepts)};

export const projectContentLoaders = ${serializeLoaderMap(manifest.projects)};
`;
}

export async function writeContentModuleRegistry(
  outputPath: string,
  manifest: ContentManifest,
) {
  const nextContent = serializeContentModuleRegistry(manifest);
  let currentContent: string | undefined;

  try {
    currentContent = await readFile(outputPath, "utf8");
  } catch (error) {
    if (
      !(error instanceof Error && "code" in error && error.code === "ENOENT")
    ) {
      throw error;
    }
  }

  if (currentContent === nextContent) {
    return { changed: false, outputPath } as const;
  }

  await mkdir(dirname(outputPath), { recursive: true });
  await writeFile(outputPath, nextContent, "utf8");
  return { changed: true, outputPath } as const;
}
